// Part: room: church belfry (interior designer). The bell stage is a 2x2 air room, x 52..53, z 10..11, y 16..17.
// The bell (52, 17, 10) hangs from the y18 deck and is the focal piece (built by the tower shell). The ladder comes up
// through the hole at (52, 15, 11) onto (52, 16, 11), which stays clear. Furnished: a barrel of ringing supplies in the
// far corner with a candle on its top, and a standing lantern beside the bell for the light.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // Origin is the room's low corner (52, 16, 10). Rows run along +x, successive rows along +z.
  layers(g, [52, 16, 10], {
    L: ["lantern", { hanging: "false" }],
    b: "barrel",
    c: ["candle", { candles: "1", lit: "true" }],
  }, [
    // y 16: the floor layer. Column x 52 stays clear (the ladder's arrival cell).
    [
      ". L",
      ". b",
    ],
    // y 17: the bell's layer. Only the candle on the barrel top; the bell cell is left alone.
    [
      "  ",
      " c",
    ],
  ]);
}

