g.set(52, 15, 11, "ladder", { facing: "north", waterlogged: "false" });
for (let y = 9; y <= 14; y++) g.set(52, y, 11, "ladder", { facing: "north", waterlogged: "false" });
g.set(52, 17, 10, "bell", { attachment: "ceiling", facing: "north", powered: "false" });
g.save("test.nbt");
console.log("saved test.nbt");
EOF
